// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ContratoDistribucion
 * @author LimpiaTuRincon
 *
 * Registro público e inmutable de contratos de distribución.
 * Guarda únicamente la huella criptográfica (hash) del documento
 * y una referencia legible (ej: número de contrato).
 */
contract ContratoDistribucion {

    /// Evento emitido al registrar un contrato
    event ContratoRegistrado(
        bytes32 indexed documentHash,
        string numeroContrato,
        address indexed registradoPor,
        uint256 timestamp
    );

    /// Evita registrar el mismo documento más de una vez
    mapping(bytes32 => bool) private registrados;

    /**
     * Registrar un contrato de distribución
     *
     * @param documentHash Hash SHA-256 del PDF del contrato
     * @param numeroContrato Número o código interno del contrato
     */
    function registrarContrato(
        bytes32 documentHash,
        string calldata numeroContrato
    ) external {
        require(documentHash != bytes32(0), "Hash invalido");
        require(!registrados[documentHash], "Contrato ya registrado");

        registrados[documentHash] = true;

        emit ContratoRegistrado(
            documentHash,
            numeroContrato,
            msg.sender,
            block.timestamp
        );
    }

    /**
     * Verificar si un contrato ya fue registrado
     *
     * @param documentHash Hash SHA-256 del documento
     */
    function contratoExiste(bytes32 documentHash)
        external
        view
        returns (bool)
    {
        return registrados[documentHash];
    }
}

contracts/MultaMunicipal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract MultaMunicipal {

    struct Multa {
        address infractor;
        uint256 monto;
        uint256 fecha;
        string motivo;
        bool pagada;
    }

    Multa[] public multas;

    function emitirMulta(
        address _infractor,
        uint256 _monto,
        string memory _motivo
    ) public {
        multas.push(
            Multa(_infractor, _monto, block.timestamp, _motivo, false)
        );
    }

    function pagarMulta(uint256 _id) public payable {
        require(!multas[_id].pagada, "Multa ya pagada");
        require(msg.value == multas[_id].monto, "Monto incorrecto");

        multas[_id].pagada = true;
    }
}

contracts/Registrodocumentos.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * RegistroDocumentos
 *
 * Registra la huella criptográfica (hash) de un documento
 * para demostrar su existencia e integridad.
 */
contract RegistroDocumentos {
    event DocumentoRegistrado(
        bytes32 indexed documentHash,
        uint256 indexed documentId,
        address indexed registradoPor,
        uint256 timestamp
    );

    mapping(bytes32 => bool) private registrados;

    function registrarDocumento(
        uint256 documentId,
        bytes32 documentHash
    ) external {
        require(documentHash != bytes32(0), "Hash invalido");
        require(!registrados[documentHash], "Documento ya registrado");

        registrados[documentHash] = true;

        emit DocumentoRegistrado(
            documentHash,
            documentId,
            msg.sender,
            block.timestamp
        );
    }

    function existe(bytes32 documentHash) external view returns (bool) {
        return registrados[documentHash];
    }
}

